// Simulates an external FX service: transient failures then success, or a permanent error
package com.bank.fxrate.client;

import com.bank.fxrate.exception.PermanentRateException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.client.ResourceAccessException;
import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicInteger;

@Component
@Slf4j
public class FlakyRateClient {

    private final AtomicInteger attempts = new AtomicInteger();

    // Fails twice (transient), succeeds on the 3rd attempt
    public BigDecimal fetchRate(String currency) {
        int n = attempts.incrementAndGet();
        if (n < 3) {
            log.warn("[client] transient failure for {} (attempt {})", currency, n);
            throw new ResourceAccessException("FX service timeout");     // TRANSIENT → retryable
        }
        log.info("[client] success for {} on attempt {}", currency, n);
        return new BigDecimal("83.250000");  // e.g. USD→INR
    }

    // Always fails permanently
    public BigDecimal fetchRatePermanentlyBad(String currency) {
        throw new PermanentRateException("Invalid currency code: " + currency);  // PERMANENT → fail fast
    }

    public void reset() { attempts.set(0); }
}
