package com.bank.fxrate.model;

import jakarta.persistence.*;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.Objects;

@Entity
@Table(name = "fx_rates")
@IdClass(FxRate.Key.class)
public class FxRate {

    @Id private String currency;
    @Id @Column(name = "rate_date") private LocalDate rateDate;
    @Column(nullable = false, precision = 15, scale = 6) private BigDecimal rate;
    @Column(name = "updated_at") private LocalDateTime updatedAt;

    protected FxRate() {}
    public FxRate(String currency, LocalDate rateDate, BigDecimal rate) {
        this.currency = currency; this.rateDate = rateDate; this.rate = rate;
        this.updatedAt = LocalDateTime.now();
    }
    public String getCurrency() { return currency; }
    public BigDecimal getRate() { return rate; }

    public static class Key implements Serializable {
        private String currency; private LocalDate rateDate;
        public Key() {}
        public Key(String currency, LocalDate rateDate) { this.currency = currency; this.rateDate = rateDate; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key k)) return false;
            return Objects.equals(currency, k.currency) && Objects.equals(rateDate, k.rateDate);
        }
        @Override public int hashCode() { return Objects.hash(currency, rateDate); }
    }
}
