package com.bank.fxrate.service;

import com.bank.fxrate.client.FlakyRateClient;
import com.bank.fxrate.exception.PermanentRateException;
import com.bank.fxrate.model.FxRate;
import com.bank.fxrate.model.SyncFailure;
import com.bank.fxrate.repository.FxRateRepository;
import com.bank.fxrate.repository.SyncFailureRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Recover;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.ResourceAccessException;
import java.math.BigDecimal;
import java.time.LocalDate;

@Service
@RequiredArgsConstructor
@Slf4j
public class FxRateService {

    private final FlakyRateClient client;
    private final FxRateRepository rateRepo;
    private final SyncFailureRepository failureRepo;

    // RETRYABLE: retry transient errors with exponential backoff; fail fast on permanent ones
    @Retryable(
        retryFor = { ResourceAccessException.class },      // TRANSIENT → retry
        noRetryFor = { PermanentRateException.class },     // PERMANENT → fail fast (no retry)
        maxAttempts = 4,                                   // 1 initial + 3 retries
        backoff = @Backoff(delay = 500, multiplier = 2, maxDelay = 10_000))
    @Transactional                                         // fresh transaction per attempt
    public BigDecimal syncRate(String currency) {
        log.info("Syncing FX rate for {}", currency);
        BigDecimal rate = client.fetchRate(currency);      // may throw transient
        // Idempotent upsert by (currency, date) → safe to re-run after a retry
        rateRepo.save(new FxRate(currency, LocalDate.now(), rate));
        log.info("Rate for {} = {}", currency, rate);
        return rate;
    }

    // RECOVER: called when all retries are exhausted. First param = exception, rest = original args.
    @Recover
    public BigDecimal recoverSyncRate(ResourceAccessException ex, String currency) {
        log.error("FX rate sync for {} failed after retries: {}", currency, ex.getMessage());
        failureRepo.save(new SyncFailure("fx-rate-sync", currency + ": " + ex.getMessage()));
        // Do NOT rethrow — let the rest of the job continue with last-known-good rates
        return null;
    }

    // Permanent path (demonstration): noRetryFor means this throws immediately, no retries
    @Retryable(retryFor = { ResourceAccessException.class }, noRetryFor = { PermanentRateException.class })
    public BigDecimal syncRateStrict(String currency) {
        return client.fetchRatePermanentlyBad(currency);  // PermanentRateException → fails fast
    }
}
