package com.bank.fxrate.job;

import com.bank.fxrate.service.FxRateService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.util.List;

@Component
@RequiredArgsConstructor
@Slf4j
public class RateSyncJob {

    private final FxRateService fxRateService;

    // Nightly rate refresh; each currency is retried independently (unit of work = one currency)
    @Scheduled(cron = "0 30 0 * * *")
    public void refreshRates() {
        log.info("Starting nightly FX rate sync");
        for (String currency : List.of("USD", "EUR", "GBP", "JPY")) {
            fxRateService.syncRate(currency);   // retry + recover applied per currency
        }
        log.info("FX rate sync finished");
    }
}
