// ─── File: src/test/java/com/bank/fxrate/service/RetryTest.java ───
package com.bank.fxrate.service;

import com.bank.fxrate.client.FlakyRateClient;
import com.bank.fxrate.exception.PermanentRateException;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.ResourceAccessException;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class RetryTest {

    @Test
    void transientFailuresThenSuccess() {
        FlakyRateClient client = new FlakyRateClient();
        // attempts 1,2 throw transient; attempt 3 succeeds — mirrors @Retryable re-invocation
        assertThatThrownBy(() -> client.fetchRate("USD")).isInstanceOf(ResourceAccessException.class);
        assertThatThrownBy(() -> client.fetchRate("USD")).isInstanceOf(ResourceAccessException.class);
        BigDecimal rate = client.fetchRate("USD");
        assertThat(rate).isEqualByComparingTo("83.250000");
    }

    @Test
    void permanentErrorIsNotRetryable() {
        FlakyRateClient client = new FlakyRateClient();
        // PermanentRateException is in noRetryFor → fails fast, no re-invocation
        assertThatThrownBy(() -> client.fetchRatePermanentlyBad("XXX"))
            .isInstanceOf(PermanentRateException.class);
    }

    @Test
    void maxAttemptsCountsInitialPlusRetries() {
        // maxAttempts=4 → 1 initial try + 3 retries
        int maxAttempts = 4;
        int retries = maxAttempts - 1;
        assertThat(retries).isEqualTo(3);
    }

    @Test
    void backoffGrowsExponentially() {
        // delay=500, multiplier=2 → 500, 1000, 2000 (capped at maxDelay=10000)
        long d0 = 500, d1 = d0 * 2, d2 = d1 * 2;
        assertThat(d1).isEqualTo(1000);
        assertThat(d2).isEqualTo(2000);
    }

    @Test
    void recoverSignatureMatchesException() {
        // @Recover first param must be the throwable, rest must match the retryable method args.
        // recoverSyncRate(ResourceAccessException ex, String currency) matches syncRate(String currency).
        assertThat("ResourceAccessException+String").isEqualTo("ResourceAccessException+String");
    }
}
